entries[12819] = { ["name"] = "Plans: Ornate Thorium Handaxe", ["text"] = "Binds when picked up\nRequires Blacksmithing (275)\n\nUse: Teaches you how to make an Ornate Thorium Handaxe.\nSell Price:\nOrnate Thorium Handaxe\nBinds when picked up\nMain Hand Axe\n43 - 81 Damage Speed 1.90\n(32.63 damage per second)\n+10 Strength\nDurability 75 / 75\nRequires Level 50\nSell Price:\nRequires Thorium Bar (20), Large Opal (2), Dense Grinding Stone (2), Rugged Leather (4)" }
