entries[12821] = { ["name"] = "Plans: Dawn's Edge", ["text"] = "Requires Blacksmithing (275)\nRequires Master Axesmith\n\nUse: Teaches you how to make Dawn's Edge.\nSell Price:\nDawn's Edge\nBinds when equipped\nOne-Hand Axe\n53 - 100 Damage Speed 2.10\n(36.43 damage per second)\nDurability 90 / 90\nRequires Level 50\nEquip: Improves your chance to get a critical strike by 1%.\nSell Price:\nRequires Thorium Bar (30), Enchanted Thorium Bar (4), Star Ruby (4), Blue Sapphire (4), Dense Grinding Stone (2), Rugged Leather (4)" }
