entries[12823] = { ["name"] = "Plans: Huge Thorium Battleaxe", ["text"] = "Binds when picked up\nRequires Blacksmithing (280)\n\nUse: Teaches you how to make a Huge Thorium Battleaxe.\nSell Price:\nHuge Thorium Battleaxe\nBinds when equipped\nTwo-Hand Axe\n114 - 172 Damage Speed 3.30\n(43.33 damage per second)\nDurability 85 / 85\nRequires Level 51\nEquip: Increased Two-handed Axes +10.\nSell Price:\nRequires Thorium Bar (40), Dense Grinding Stone (6), Rugged Leather (6)" }
entries[12824] = { ["name"] = "Plans: Enchanted Battlehammer", ["text"] = "Requires Blacksmithing (280)\nRequires Master Hammersmith\n\nUse: Teaches you how to make an Enchanted Battlehammer.\nSell Price:\nEnchanted Battlehammer\nBinds when equipped\nTwo-Hand Mace\n100 - 150 Damage Speed 2.60\n(48.08 damage per second)\nDurability 100 / 100\nRequires Level 51\nEquip: Increases your chance to parry an attack by 1%.\n\nEquip: Improves your chance to hit by 2%.\nSell Price:\nRequires Thorium Bar (20), Enchanted Thorium Bar (6), Huge Emerald (2), Powerful Mojo (4), Rugged Leather (4)" }
entries[12825] = { ["name"] = "Plans: Blazing Rapier", ["text"] = "Requires Blacksmithing (280)\nRequires Master Swordsmith\n\nUse: Teaches you how to make a Blazing Rapier.\nSell Price:\nBlazing Rapier\nBinds when equipped\nOne-Hand Sword\n44 - 82 Damage Speed 1.70\n(37.06 damage per second)\nDurability 90 / 90\nRequires Level 51\nChance on hit: Burns the enemy for 100 damage over 30 sec.\nSell Price:\nRequires Enchanted Thorium Bar (10), Essence of Fire (4), Heart of Fire (4), Azerothian Diamond (2), Dense Grinding Stone (2)" }
entries[12827] = { ["name"] = "Plans: Serenity", ["text"] = "Requires Blacksmithing (285)\nRequires Master Hammersmith\n\nUse: Teaches you how to make Serenity.\nSell Price:\nSerenity\nBinds when equipped\nMain Hand Mace\n52 - 98 Damage Speed 2.00\n(37.50 damage per second)\nDurability 90 / 90\nRequires Level 52\nChance on hit: Dispels a magic effect on the current foe.\nSell Price:\nRequires Enchanted Thorium Bar (6), Arcanite Bar (2), Powerful Mojo (4), Large Opal (2), Blue Sapphire (2), Huge Emerald" }
